head.script:
scwin.test = function(v, dv, row, col) {
    //alert("CustomFormater OK");
    log = "CustomFormater OK";
    return v
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행한다.
    //1. Run the sample file.
    //Verify 1. input=textImage일 경우 customFormater가 적용되어 알림창("CustomFormater OK")이 보여진다.
    // 1. In the case of input = textImage, the customFormater is applied and the notification window ("CustomFormater OK") is displayed.
    WebSquare.wUnit.addCommand("assert", "log", "CustomFormater OK");
    WebSquare.wUnit.addCommand("pause", "2000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
